const EMPTY = { CAT: {}, providers: [], byId: {}, TOTAL: 0, fmt: String }
class Component extends DCLogic {
  state = { sel: this.props.initial ?? null, filter: 'all', add: false, aq: '', acat: 'all', picks: [] }
  componentDidMount() {
    if (!RELAY)
      this._i = setInterval(() => {
        if (RELAY) {
          clearInterval(this._i)
          this.forceUpdate()
        }
      }, 40)
  }
  componentWillUnmount() {
    clearInterval(this._i)
  }
  componentDidUpdate(prev) {
    if (prev.initial !== this.props.initial && this.props.initial) this.setState({ sel: this.props.initial })
    if (prev.focus !== this.props.focus && this.props.focus) this.setState({ sel: this.props.focus, filter: 'all' })
  }
  renderVals() {
    const R = RELAY ?? EMPTY,
      S = this.state,
      all = this.props.lists ?? []
    const visible = all
    const sel = all.find((l) => l.id === S.sel) ?? visible[0] ?? all[0]
    const meta = (l) => `${l.ids.length} Provider${l.ids.length === 1 ? '' : 's'} · Updated ${l.updated}`
    const catLabel = (k) => (k === 'all' ? 'All categories' : R.CAT[k]?.label)
    const many = sel && sel.ids.length > 1
    const chip = (k, label, cur, fn) => ({
      label,
      pick: () => fn(k),
      bg: cur === k ? 'rgba(255,255,255,.08)' : 'transparent',
      fg: cur === k ? '#f7f8f8' : '#8a8f98',
    })
    const cats = Object.entries(R.CAT)
    const q = S.aq.trim().toLowerCase(),
      aOn = S.add
    const opts = R.providers
      .filter(
        (p) =>
          (S.acat === 'all' || p.kind === S.acat) &&
          (!q || (p.name + ' ' + p.hq + ' ' + p.cat).toLowerCase().includes(q)),
      )
      .slice(0, 50)
    return {
      total: R.fmt(R.TOTAL),
      filters: [
        chip('all', 'All', S.filter, (k) => this.setState({ filter: k })),
        ...cats.map(([k, v]) => chip(k, v.label, S.filter, (k2) => this.setState({ filter: k2 }))),
      ],
      lists: visible.map((l) => ({
        ...l,
        meta: meta(l),
        open: () => this.setState({ sel: l.id }),
        bg: sel && l.id === sel.id ? 'rgba(255,255,255,.05)' : 'transparent',
        fg: sel && l.id === sel.id ? '#f7f8f8' : '#d4d6da',
      })),
      filterEmpty: visible.length === 0 && all.length > 0,
      hasSel: !!sel,
      noSel: !sel,
      sel: sel
        ? {
            ...sel,
            meta: meta(sel),
            catLabel: catLabel(sel.kind),
            accent: sel.kind === 'all' ? '#8a8f98' : R.CAT[sel.kind]?.accent,
          }
        : { name: '' },
      items: sel
        ? sel.ids
            .map((id) => R.byId[id])
            .filter(Boolean)
            .sort((a, b) => b.score - a.score)
            .map((p, i) => ({
              ...p,
              rank: String(i + 1).padStart(2, '0'),
              scoreW: p.score + '%',
              remove: () => this.props.onRemoveItem?.(sel.id, p.id),
            }))
        : [],
      hasItems: !!sel && sel.ids.length > 0,
      noItems: !!sel && sel.ids.length === 0,
      onNote: (e) => this.props.onNote?.(sel.id, e.target.value),
      create: () => this.props.onCreate?.(),
      edit: () => sel && this.props.onEdit?.(sel.id),
      cmp: { fg: many ? '#0f1011' : '#62666d', bg: many ? '#f7f8f8' : 'rgba(255,255,255,.05)' },
      compare: () => many && this.props.onCompare?.(sel.ids.slice(0, 4)),
      openAdd: () =>
        this.setState({ add: true, picks: [], aq: '', acat: sel && sel.kind !== 'all' ? sel.kind : 'all' }),
      closeAdd: () => this.setState({ add: false }),
      am: {
        op: aOn ? 1 : 0,
        pe: aOn ? 'auto' : 'none',
        tf: aOn ? 'translate(-50%,-50%) scale(1)' : 'translate(-50%,-48%) scale(.98)',
      },
      aq: S.aq,
      onAq: (e) => this.setState({ aq: e.target.value }),
      addCats: [
        chip('all', 'All', S.acat, (k) => this.setState({ acat: k })),
        ...cats.map(([k, v]) => chip(k, v.label, S.acat, (k2) => this.setState({ acat: k2 }))),
      ],
      addOptions: opts.map((p) => {
        const already = !!sel && sel.ids.includes(p.id),
          on = already || S.picks.includes(p.id)
        return {
          ...p,
          already,
          toggle: () =>
            !already &&
            this.setState((s) => ({
              picks: s.picks.includes(p.id) ? s.picks.filter((x) => x !== p.id) : [...s.picks, p.id],
            })),
          bg: S.picks.includes(p.id) ? 'rgba(111,227,180,.04)' : 'transparent',
          boxBg: on ? (already ? '#3a3c40' : '#6fe3b4') : 'transparent',
          boxRing: on ? 'none' : 'inset 0 0 0 1.5px rgba(255,255,255,.2)',
          checkOp: on ? 1 : 0,
        }
      }),
      addCount: S.picks.length ? `${S.picks.length} selected` : 'Select Providers to add',
      addBtn: { fg: S.picks.length ? '#0f1011' : '#62666d', bg: S.picks.length ? '#f7f8f8' : 'rgba(255,255,255,.05)' },
      confirmAdd: () => {
        if (!S.picks.length || !sel) return
        this.props.onAddItems?.(sel.id, S.picks)
        this.setState({ add: false, picks: [] })
      },
    }
  }
}

